import React from 'react';
import { useParams } from 'react-router-dom';
import './CursoDetalle.css'; // Estilos específicos
import Inscripcion from './Inscripcion'; // Importamos el formulario de inscripción

const CursoDetalle = () => {
  const { id } = useParams(); // Obtener el ID del curso desde la URL

  // Datos del curso
  const curso = {
    id,
    nombre: id === '1' ? 'Curso de <span class="highlight">REACT</span>' : 'Curso de <span class="highlight">JAVASCRIPT</span>',
    descripcion: id === '1'
      ? 'Aprende a desarrollar aplicaciones web modernas con <span class="highlight">React</span>. Desde los fundamentos hasta conceptos <span class="highlight">avanzados</span>.'
      : 'Domina <span class="highlight">JavaScript</span>, el lenguaje esencial para el desarrollo web. Conoce buenas prácticas y frameworks populares.',
    puntos: id === '1'
      ? ['Componentes reutilizables', 'Gestión de estado con <span class="highlight">hooks</span>', 'Integración con <span class="highlight">APIs</span>']
      : ['Manipulación del DOM', 'Programación asincrónica', 'ES6 y más allá'],
  };

  return (
    <div className="curso-container">
      <div className="curso-detalle">
        <h1 className="titulo-curso">{curso.nombre}</h1>
        <p className="descripcion" dangerouslySetInnerHTML={{ __html: curso.descripcion }}></p>
        <ul>
          {curso.puntos.map((punto, index) => (
            <li key={index} dangerouslySetInnerHTML={{ __html: `✅ ${punto}` }}></li>
          ))}
        </ul>
      </div>

      <Inscripcion cursoId={curso.id} />
    </div>
  );
};

export default CursoDetalle;
